async (page) => {
  const fs = require('fs');
  const { exec } = require('child_process');

  // Make the script executable
  exec('chmod +x /tmp/mcp-workspace/network_monitor.sh', (error, stdout, stderr) => {
    if (error) {
      console.error(`Error making script executable: ${error}`);
      return;
    }
    console.log('Script made executable successfully');
  });

  // Start the script in the background
  exec('nohup /tmp/mcp-workspace/network_monitor.sh > /tmp/mcp-workspace/script_output.log 2>&1 &', (error, stdout, stderr) => {
    if (error) {
      console.error(`Error starting script: ${error}`);
      return;
    }
    console.log('Network monitoring script started in background');
  });

  return 'Script made executable and started in background';
}

