async (page) => {
  const { execSync } = require('child_process');

  try {
    // Make the test script executable
    execSync('chmod +x /tmp/mcp-workspace/network_monitor_test.sh');

    // Run the test script synchronously
    const output = execSync('bash /tmp/mcp-workspace/network_monitor_test.sh', { encoding: 'utf-8' });
    console.log('Test script output:', output);

    // Read and display the log file
    const logContent = execSync('cat /tmp/mcp-workspace/network_log.txt', { encoding: 'utf-8' });
    console.log('Log file content:', logContent);

    return 'Network monitoring test completed successfully';
  } catch (error) {
    console.error('Error running test script:', error.message);
    return 'Error occurred during test';
  }
}

